patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..a6a2c60
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,40 @@
+"use strict";
+
+// Reproduction: `no-unused-expressions` reports the 'use strict' directive when
+// the parser is run with ecmaVersion 3 (core-js lints `packages/core-js*/**` with
+// ecmaVersion: 3). Works on 9.24.0, fails on 9.25.0.
+//
+// Run from the repo root:  node repro/no-unused-expressions-use-strict.js
+
+const { Linter } = require("../lib/api");
+
+const code = "'use strict';\n";
+const options = {
+	allowShortCircuit: true,
+	allowTernary: true,
+	allowTaggedTemplates: true,
+};
+let failed = false;
+
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const linter = new Linter();
+	const messages = linter.verify(code, [
+		{
+			languageOptions: { ecmaVersion, sourceType: "script" },
+			rules: { "no-unused-expressions": ["error", options] },
+		},
+	]);
+
+	console.log(`ecmaVersion ${ecmaVersion}: ${messages.length} problem(s)`);
+	for (const m of messages) {
+		console.log(`  ${m.line}:${m.column}  ${m.message}  ${m.ruleId}`);
+	}
+	if (ecmaVersion === 3 && messages.length > 0) {
+		failed = true;
+	}
+}
+
+if (failed) {
+	console.log("\nBUG REPRODUCED: 'use strict' reported with ecmaVersion 3");
+	process.exitCode = 1;
+}
